def _open_runs(player: PlayerTarget) -> list[RunRecord]:
    return [open_run(path) for path in player.runs]


# What may differ between an ablation and its full agent: the switch itself, the run's name,
# and its budget and seed, which the check below compares group against group.
_PER_RUN = frozenset({"name", "ablation", "steps", "seed"})


def _agent_of(settings: RunSettings) -> tuple[object, ...]:
    """The settings an ablation shares with its full agent."""
    return tuple(
        getattr(settings, f.name) for f in dataclasses.fields(settings) if f.name not in _PER_RUN
    )


def _check_ablation(
    name: str, runs: Sequence[RunRecord], groups: Mapping[str, Sequence[RunRecord]]
) -> None:
    """ValueError unless a full agent's run group has this ablation's seeds and steps (ABL-04)."""
    agent = _agent_of(runs[0].settings)
    fulls = [
        (full, full_runs)
        for full, full_runs in groups.items()
        if full_runs
        and full_runs[0].settings.ablation == "none"
        and _agent_of(full_runs[0].settings) == agent
    ]
    if not fulls:
        raise ValueError(f"ablation {name!r}: no full agent among the report's run players")
    full, full_runs = fulls[0]
    seeds, full_seeds = _seeds(runs), _seeds(full_runs)
    if seeds != full_seeds:
        raise ValueError(f"ablation {name!r} has seeds {seeds}, its full agent {full!r} {full_seeds}")
    steps, full_steps = _steps(runs), _steps(full_runs)
    if steps != full_steps:
        raise ValueError(f"ablation {name!r} has steps {steps}, its full agent {full!r} {full_steps}")


def _seeds(runs: Sequence[RunRecord]) -> list[int]:
    return sorted(r.settings.seed for r in runs)


def _steps(runs: Sequence[RunRecord]) -> list[int]:
    return sorted({r.settings.steps for r in runs})

